describe("Cart.totals pricing pipeline", () => {
  it("computes subtotal as sum of (price * qty)", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 * 1000 = 2000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("returns all zeros for empty cart", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount((s) => Math.floor(s * 0.1)), // 10%
      taxCalculator: mockTax((t, _r) => Math.floor(t * 0.08)), // 8%
    });
    cart.add(widget, 10); // subtotal 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10% of 10000
    // Tax on discounted: 8% of 9000 = 720
    expect(t.taxCents).toBe(720);
  });

  it("clamps discount to [0, subtotal]", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => 99999), // way more than subtotal
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // fully discounted
  });

  it("clamps negative discount to 0", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => -500),
    });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const cart = new Cart({
      taxCalculator: mockTax(() => -100),
    });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const cart = new Cart({
      shippingCalculator: mockShipping(() => -50),
    });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => 200),
      taxCalculator: mockTax(() => 80),
      shippingCalculator: mockShipping(() => 500),
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(80);
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("defaults to NoDiscount, NoTax, FreeShipping", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(2000);
  });

  it("uses configured region for tax", () => {
    const taxCalc = mockTax((_t, _r) => 100);
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const taxCalc = mockTax((_t, _r) => 0);
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

