      expect(calc.computeShippingCents([makeLine("a", 501)], 100)).toBe(600);
    });

    it("selects highest bracket for weight at upper boundary (5000g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 5000)], 100)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 5001)], 100)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 9999)], 100)).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
