import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

const emptyLines: readonly CartLine[] = [];

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 1000)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents(emptyLines, 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents and zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100)], 3000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents(emptyLines, 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(599);
    });

    it("returns flat fee when freeOverCents is not set", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100)], 99999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents(emptyLines, 5000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket for weight at boundary (500g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 500)], 100)).toBe(300);
    });

    it("selects next bracket for weight just above boundary (501g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 501)], 100)).toBe(600);
    });

    it("selects highest bracket for weight at upper boundary (5000g)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 5000)], 100)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calc.computeShippingCents([makeLine("a", 5001)], 100)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([makeLine("a", 9999)], 100)).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g * 2 = 600g => second bracket (up to 1000g) = 600 cents
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 100),
      ).toBe(600);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(calc.computeShippingCents([makeLine("a", 400)], 100)).toBe(300);
    });
  });
});

