import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

// ── Helpers ──

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

function mockDiscount(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}

function mockTax(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}

function mockShipping(fn: (lines: any, s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ── Cart.add / remove / updateQuantity / clear / itemCount ──

describe("Cart line management", () => {
  it("adds a product and reports correct itemCount", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks different products independently", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the line quantity", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 5)).toThrow("Product nope is not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });
});

// ── Cart.snapshot ──

describe("Cart.snapshot", () => {
  it("returns a deep copy that is isolated from the cart", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 0;
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

// ── Cart.totals (pricing pipeline) ──

describe("Cart.totals pricing pipeline", () => {
  it("computes subtotal as sum of (price * qty)", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 * 1000 = 2000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("returns all zeros for empty cart", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount((s) => Math.floor(s * 0.1)), // 10%
      taxCalculator: mockTax((t, _r) => Math.floor(t * 0.08)), // 8%
    });
    cart.add(widget, 10); // subtotal 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10% of 10000
    // Tax on discounted: 8% of 9000 = 720
    expect(t.taxCents).toBe(720);
  });

  it("clamps discount to [0, subtotal]", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => 99999), // way more than subtotal
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // fully discounted
  });

  it("clamps negative discount to 0", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => -500),
    });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const cart = new Cart({
      taxCalculator: mockTax(() => -100),
    });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const cart = new Cart({
      shippingCalculator: mockShipping(() => -50),
    });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => 200),
      taxCalculator: mockTax(() => 80),
      shippingCalculator: mockShipping(() => 500),
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(80);
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("defaults to NoDiscount, NoTax, FreeShipping", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(2000);
  });

  it("uses configured region for tax", () => {
    const taxCalc = mockTax((_t, _r) => 100);
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const taxCalc = mockTax((_t, _r) => 0);
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

// ── Cart.checkout ──

describe("Cart.checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 1); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and passes on available stock", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
  });

  it("throws InventoryError when stock is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w1");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w1");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(widget, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // 8.75% of 1000 = 87.5 → 87
    expect(result.totals.taxCents).toBe(87);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("composes discount + async tax + shipping correctly", async () => {
    const cart = new Cart({
      discountPolicy: mockDiscount((s) => Math.floor(s * 0.1)), // 10%
      shippingCalculator: mockShipping(() => 500),
      region: "US",
    });
    cart.add(widget, 10); // subtotal 10000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08), // 8%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(1000);
    // Tax on discounted: 8% of 9000 = 720
    expect(result.totals.taxCents).toBe(720);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 720 + 500);
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("checks all items against inventory in order", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("checkout with priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: mockDiscount(() => 0),
      shippingCalculator: mockShipping(() => 0),
    });
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    expect(result.totals.subtotalCents).toBe(1000); // 2 * 500
    expect(result.totals.taxCents).toBe(100); // 10% of 1000
    expect(result.lines[0].product.unitPriceCents).toBe(500);
  });
});

